sharedHelpers:
static int readable(void *p,U64 size) {
 Range r;U64 a=(U64)p,b=a+size;int i;
 if(!a || b<a)return 0;
 for(i=0;i<4 && a<b;i++){
  if(virtual_query((void *)a,&r,sizeof(r))!=sizeof(r) || r.state!=0x1000 ||
   (r.protect&0x101) || !(r.protect&0xee) || (U64)r.base+r.size<=a)return 0;
  a=(U64)r.base+r.size;
 }
 return a>=b;
}
static void *ref(void *p,U32 off){return p && readable((char *)p+off,8)?*(void **)((char *)p+off):0;}
static U32 word(void *p,U32 off){return p && readable((char *)p+off,4)?*(U32 *)((char *)p+off):0;}
static U64 relative(void *p){U64 a=(U64)p,b=(U64)&module_base;return a>=b && a-b<module_size?a-b:0;}
static int catalog(U32 id){
 U32 low=0,high=TARGET_COUNT,mid;
 while(low<high){mid=(low+high)/2;if(target_ids[mid]<id)low=mid+1;else high=mid;}
 return low<TARGET_COUNT && target_ids[low]==id;
}
/* Exact local property decoder independently checked against 0x12e9de40.
 * Decode only HP/max HP; never call a setter or copy an encoded property back. */
static const unsigned char *table(U32 *reason,U32 *rows,U32 *columns){
 void *root=ref(&root_slot,0),*t=ref(root,0x24e70),*dims=ref(t,0x10);
 *rows=word(dims,0);*columns=word(dims,0x10);
 if(!root){*reason=2;return 0;}if(!t){*reason=3;return 0;}
 if(!readable(dims,0x18) || word(dims,0)<12 || word(dims,0)>256 ||
  *(U64 *)((char *)dims+0x10)!=256 || !readable(t,0x20+12*256)){*reason=4;return 0;}
 *reason=0;
 return (const unsigned char *)t+0x20;
}
static int decode(void *p,const unsigned char *t,float *out,U32 *reason){
 U32 h=0,words[3]={0,0,0},i,bits;unsigned char *v=p;
 if(!readable(p,16)){*reason=5;return 0;}
 if(!t)return 0;
 /* Native decoder returns zero for an entirely uninitialized property. */
 if(!*(U64 *)p && !*(U64 *)((char *)p+8)){*out=0;*reason=0;return 1;}
 for(i=0;i<4;i++)h|=(U32)t[(8+i)*256+v[i]]<<(i*8);
 if(h>0x7fffffff){*reason=6;return 0;}
 /* All THREE words use rows 8,9,10,11, restarting for each word.
  * The old i*256 expression incorrectly read rows 0..11. */
 for(i=0;i<12;i++)words[i/4]|=(U32)t[(8+i%4)*256+v[4+(i+h%12)%12]]<<((i%4)*8);
 bits=h^words[1];if((words[0]^bits)!=words[2]){*reason=7;return 0;}
 if((bits&0x7f800000)==0x7f800000){*reason=8;return 0;}
 *out=*(float *)&bits;
 if(!(*out>=0 && *out<=25000000.0f)){*reason=8;return 0;}
 *reason=0;return 1;
}
U32 hp_decode_test(void *p,float *out){U32 reason=0,rows,columns;const unsigned char *t=table(&reason,&rows,&columns);return decode(p,t,out,&reason);}
static void *component(void *entity){
 void *a=ref(ref(entity,0x198),0x28),*c;
 if(word(a,0x18)<=13)return 0;
 c=ref(a,0x20+13*8);
 return readable(c,0x1c8) && ref(c,0x28)==entity && word(c,0x14)==word(entity,0x3d4)?c:0;
}
